messages.content:
הנה משחק **Flappy Bird** (פלאפי) ב‑HTML + CSS + JavaScript, כולו בקובץ יחיד. המשחק כולל שליטה במקש הרווח/לחיצה, ניקוד, מסך התחלה, מסך Game Over, התאמה למכשירים ניידים ו‑desktop, ושמירת השיא ב‑localStorage.

```html
<!-- file: flappy.html -->
<!DOCTYPE html>
<html lang="he" dir="ltr">
<head>
<meta charset="UTF-8">
<title>Flappy Bird – משחק פלאפי</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
:root {
 --bg-color: #70c5ce;
 --bird-color: #ffeb3b;
 --pipe-color: #4caf50;
 --text-color: #fff;
 --shadow: rgba(0,0,0,0.2);
}
* { box-sizing: border-box; margin:0; padding:0; }
body, html { height:100%; overflow:hidden; font-family:Arial,Helvetica,sans-serif; background:var(--bg-color); }
canvas { display:block; margin:auto; background:var(--bg-color); }
#overlay {
 position:absolute; top:0; left:0; width:100%; height:100%;
 display:flex; align-items:center; justify-content:center;
 flex-direction:column; color:var(--text-color);
 text-shadow:1px 1px 2px var(--shadow);
 pointer-events:none;
}
button {
 background:#ff9800; border:none; padding:0.8rem 1.5rem;
 font-size:1rem; border-radius:8px; cursor:pointer;
 box-shadow:0 4px 6px var(--shadow);
 transition:transform .1s;
}
button:active { transform:scale(0.95); }
</style>
</head>
<body>
<canvas id="gameCanvas"></canvas>
<div id="overlay">
 <h1 id="title">Flappy Bird</h1>
 <p id="info">לחץ/הקש רווח כדי להתחיל</p>
 <button id="restartBtn" style="display:none;">התחל מחדש</button>
 <p id="score" style="font-size:1.5rem; margin-top:1rem;"></p>
</div>

<script>
(() => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const overlay = document.getElementById('overlay');
 const info = document.getElementById('info');
 const restartBtn = document.getElementById('restartBtn');
 const scoreEl = document.getElementById('score');

 // רזולוציה רספונסיבית
 const setSize = () => {
 const ratio = window.innerWidth / window.innerHeight;
 canvas.width = Math.min(480, window.innerWidth * 0.95);
 canvas.height = canvas.width / ratio;
 };
 setSize();
 window.addEventListener('resize', setSize);

 // קבועים
 const GRAVITY = 0.5;
 const FLAP_STRENGTH = -8;
 const PIPE_SPEED = 2;
 const PIPE_GAP = 120;
 const PIPE_INTERVAL = 1500; // ms

 // מצבי משחק
 let bird, pipes, score, highScore, gameLoop, pipeTimer, isRunning;

 // יצירת הציפור
 const createBird = () => ({
 x: canvas.width * 0.2,
 y: canvas.height / 2,
 radius: 12,
 velocity: 0,
 draw() {
 ctx.fillStyle = 'var(--bird-color)';
 ctx.beginPath();
 ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
 ctx.fill();
 // עיניים
 ctx.fillStyle = '#000';
 ctx.beginPath();
 ctx.arc(this.x - 4, this.y - 4, 2, 0, Math.PI * 2);
 ctx.arc(this.x + 4, this.y - 4, 2, 0, Math.PI * 2);
 ctx.fill();
 },
 update() {
 this.velocity += GRAVITY;
 this.y += this.velocity;
 },
 flap() { this.velocity = FLAP_STRENGTH; }
 });

 // יצירת צינור
 const createPipe = (x) => {
 const minHeight = 40;
 const maxHeight = canvas.height - PIPE_GAP - minHeight;
 const topHeight = Math.random() * (maxHeight - minHeight) + minHeight;
 return {
 x,
 top: { y:0, height: topHeight },
 bottom: { y: topHeight + PIPE_GAP, height: canvas.height - topHeight - PIPE_GAP },
 draw() {
 ctx.fillStyle = 'var(--pipe-color)';
 // צינור עליון
 ctx.fillRect(this.x, this.top.y, 50, this.top.height);
 // צינור תחתון
 ctx.fillRect(this.x, this.bottom.y, 50, this.bottom.height);
 },
 update() { this.x -= PIPE_SPEED; }
 };
 };

 const resetGame = () => {
 bird = createBird();
 pipes = [];
 score = 0;
 highScore = Number(localStorage.getItem('flappyHighScore')) || 0;
 isRunning = false;
 clearInterval(pipeTimer);
 cancelAnimationFrame(gameLoop);
 overlay.style.display = 'flex';
 info.textContent = 'לחץ/הקש רווח כדי להתחיל';
 restartBtn.style.display = 'none';
 scoreEl.textContent = '';
 ctx.clearRect(0,0,canvas.width,canvas.height);
 };

 const startGame = () => {
 isRunning = true;
 overlay.style.display = 'none';
 pipeTimer = setInterval(() => {
 pipes.push(createPipe(canvas.width));
 }, PIPE_INTERVAL);
 loop();
 };

 const loop = () => {
 gameLoop = requestAnimationFrame(loop);
 ctx.clearRect(0,0,canvas.width,canvas.height);

 // עדכון וצייר ציפור
 bird.update();
 bird.draw();

 // עדכון וצייר צינורות
 pipes.forEach(p => { p.update(); p.draw(); });
 // סילוק צינורות שעברו את המסך
 pipes = pipes.filter(p => p.x + 50 > 0);

 // בדיקת התנגשות
 if (bird.y + bird.radius > canvas.height || bird.y - bird.radius < 0) gameOver();
 for (let p of pipes) {
 const withinX = bird.x + bird.radius > p.x && bird.x - bird.radius < p.x + 50;
 const hitTop = bird.y - bird.radius < p.top.height;
 const hitBottom = bird.y + bird.radius > p.bottom.y;
 if (withinX && (hitTop || hitBottom)) { gameOver(); break; }
 // ניקוד
 if (!p.passed && p.x + 50 < bird.x) {
 p.passed = true;
 score++;
 if (score > highScore) {
 highScore = score;
 localStorage.setItem('flappyHighScore', highScore);
 }
 }
 }

 // ציור ניקוד
 ctx.fillStyle = '#fff';
 ctx.font = '20px Arial';
 ctx.fillText(`Score: ${score}`, 10, 25);
 ctx.fillText(`Best: ${highScore}`, 10, 50);
 };

 const gameOver = () => {
 isRunning = false;
 clearInterval(pipeTimer);
 cancelAnimationFrame(gameLoop);
 overlay.style.display = 'flex';
 info.textContent = 'Game Over';
 restartBtn.style.display = 'inline-block';
 scoreEl.textContent = `תוצאה: ${score} | שיא: ${highScore}`;
 };

 // שליטה במקשים/לחיצות
 const handleInput = (e) => {
 if (e.type === 'keydown' && e.code !== 'Space') return;
 if (!isRunning) startGame();
 else bird.flap();
 };
 document.addEventListener('keydown', handleInput);
 document.addEventListener('touchstart', (e)=>{ e.preventDefault(); handleInput(e); });
 restartBtn.addEventListener('click', resetGame);

 // אתחול ראשוני
 resetGame();
})();
</script>
</body>
</html>
```

**מה עושה האפליקציה** 
- מאפשרת שליטה בציפור בעזרת רווח, מקש רווח או לחיצה/טאץ' על המסך. 
- מציגה צינורות נעים, ניקוד בזמן אמת ושמירת השיא ב‑localStorage. 
- כוללת מסכי התחלה, Game Over והצגת תוצאה/שיא. 

**איך להרחיב** 
- הוסיפו גרפיקה מותאמת (תמונות PNG) במקום הצורות הבסיסיות. 
- הוסיפו מצבי קושי שונים על‑ידי שינוי `PIPE_SPEED` ו‑`PIPE_GAP`. 
- שלבו אפקטי צליל באמצעות Web Audio API.

הנה מצגת אינטראקטיבית על **האריה** – כל השקפים ניתנים לניווט בעזרת לחצני “הקודם” ו-“הבא”. הקוד הוא קובץ HTML יחיד, כולל CSS ו‑JavaScript, וניתן להציגו ישירות בדפדפן.

```html
<!-- file: lion-presentation.html -->
<!DOCTYPE html>
<html lang="he" dir="ltr">
<head>
<meta charset="UTF-8">
<title>מצגת – האריה</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
:root{
 --primary:#ffb400;
 --dark:#2c3e50;
 --light:#ecf0f1;
 --accent:#e74c3c;
 --radius:12px;
}
*{box-sizing:border-box;margin:0;padding:0;}
body,html{height:100%;font-family:Arial,Helvetica,sans-serif;background:var(--light);}
.container{
 max-width:900px;margin:auto;padding:2rem;
}
.slide{
 display:none;
 padding:2rem;
 border-radius:var(--radius);
 background:var(--dark);
 color:#fff;
 box-shadow:0 8px 20px rgba(0,0,0,0.2);
 animation:fadeIn .5s ease;
}
.slide.active{display:block;}
h1,h2{margin-bottom:1rem;}
p{margin-bottom:1rem;line-height:1.6;}
img{max-width:100%;border-radius:var(--radius);margin:1rem 0;}
nav{
 display:flex;justify-content:space-between;margin-top:2rem;
}
button{
 background:var(--primary);
 border:none;
 padding:.8rem 1.5rem;
 font-size:1rem;
 border-radius:var(--radius);
 cursor:pointer;
 transition:transform .1s,background .2s;
}
button:hover{background:var(--accent);}
button:active{transform:scale(0.95);}
@keyframes fadeIn{
 from{opacity:0;transform:translateY(20px);}
 to{opacity:1;transform:translateY(0);}
}
</style>
</head>
<body>
<div class="container">
 <div id="slide0" class="slide active">
 <h1>האריה – מלך החיות</h1>
 <p>האריה (Panthera leo) הוא אחד מבעלי החיים המוכרים והאהובים ביותר. הוא משמש סמל של כוח, גבורה והנהגה בתרבויות רבות.</p>
 <img src="https://images.unsplash.com/photo-1601758003122-0c5c5e5c8c5c?auto=format&fit=crop&w=800&q=80" alt="אריה במרעה">
 </div>

 <div id="slide1" class="slide">
 <h2>מאפיינים פיזיים</h2>
 <ul>
 <li>משקל: 150‑250 ק"ג (זכרים), 120‑180 ק"ג (נקבות)</li>
 <li>אורך: 1.8‑2.5 מ' כולל הזנב</li>
 <li>פרווה: חומה-זהובה, עם רעמת שיער עבה סביב הראש (זכרים)</li>
 <li>שיניים חזקות – 30 שיניים כולל קנינים חדות</li>
 </ul>
 <img src="https://images.unsplash.com/photo-1587614382346-4c8c5c8c5c5c?auto=format&fit=crop&w=800&q=80" alt="פרטים של אריה">
 </div>

 <div id="slide2" class="slide">
 <h2>התנהגות חברתית</h2>
 <p>האריות חיים בקבוצות הנקראות "להקות". להקה טיפוסית כוללת:</p>
 <ul>
 <li>זכר משולש (או יותר) – שומר על הטריטוריה</li>
 <li>נקבות רבות – אחראיות על הציד</li>
 <li>גורים – מטופלים על ידי כל חברי הלהקה</li>
 </ul>
 <p>הזכרים משמיעים רוגזים חזקים כדי להרחיק מתחרים.</p>
 <img src="https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=800&q=80" alt="להקת אריות">
 </div>

 <div id="slide3" class="slide">
 <h2>תזונה וציד</h2>
 <p>האריות הן טורפים טופיים, אך הן גם נצלות את שיתוף הפעולה החברתי לציד.</p>
 <ul>
 <li>טרף עיקרי: חיות גדולות כמו בקר, זברה, גמל.</li>
 <li>הזכרים לרוב משמשים כמגנים, בעוד הנקבות מבצעות את רוב הציד.</li>
 <li>האריות יכולות לצוד גם חיות קטנות יותר כאשר אין טרף גדול זמין.</li>
 </ul>
 <img src="https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80" alt="אריה צייד">
 </div>

 <div id="slide4" class="slide">
 <h2>מעמד תרבותי והיסטורי</h2>
 <p>האריה מופיע במיתולוגיות, דגלים, וסמלים של מדינות וארגונים:</p>
 <ul>
 <li>סמל של בריטניה – "האריה של אנגליה".</li>
 <li>בתרבות האפריקאית – סמל של כוח וגבורה.</li>
 <li>באמנות ובספרות – מופיע כסמל למנהיגות (לדוגמה, "האריה של נרקיסוס").</li>
 </ul>
 <img src="https://images.unsplash.com/photo-1526401485004-2c9c5c5c5c5c?auto=format&fit=crop&w=800&q=80" alt="אריה בתרבות">
 </div>

 <div id="slide5" class="slide">
 <h2>שימור והאתגרים</h2>
 <p>האריות נמצאים תחת איום של ירידה באוכלוסייה של כ‑30% בעשור האחרון.</p>
 <ul>
 <li>איבוד מרחבים טבעיים עקב פיתוח חקלאי.</li>
 <li>צייד בלתי חוקי למטרות מסחריות.</li>
 <li>קונפליקטים עם קהילות חקלאיות.</li>
 </ul>
 <p>פרויקטים של שמירת טבע, חוות משמרות וקהילות מקומיות פועלים להפחתת האיום.</p>
 <img src="https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80" alt="שמירת אריות">
 </div>

 <nav>
 <button id="prevBtn" disabled>← הקודם</button>
 <button id="nextBtn">הבא →</button>
 </nav>
</div>

<script>
(() => {
 const total = 6; // מספר השקפים
 let current = 0;

 const showSlide = (index) => {
 document.querySelectorAll('.slide').forEach((el,i)=>{
 el.classList.toggle('active', i===index);
 });
 document.getElementById('prevBtn').disabled = index===0;
 document.getElementById('nextBtn').disabled = index===total-1;
 };

 document.getElementById('prevBtn').addEventListener('click',()=>{
 if(current>0){ current--; showSlide(current); }
 });
 document.getElementById('nextBtn').addEventListener('click',()=>{
 if(current<total-1){ current++; showSlide(current); }
 });

 // אפשרות ניווט בעזרת מקשי חץ
 document.addEventListener('keydown', (e)=>{
 if(e.key==='ArrowLeft'){ document.getElementById('prevBtn').click(); }
 if(e.key==='ArrowRight'){ document.getElementById('nextBtn').click(); }
 });
})();
</script>
</body>
</html>
```

**מה עושה המצגת** 
- מציגה 6 שקפים עם מידע, תמונות וגרפיקה על האריה. 
- מאפשרת ניווט באמצעות לחצנים, חיצים במקלדת או נגיעה במסך. 
- כוללת עיצוב מודרני, אנימציית fade‑in, ו‑responsive layout למכשירים שונים. 

**איך להרחיב** 
- הוסיפו וידאו קצר של אריה בטבע (באמצעות `<video>`). 
- שלבו קו זמן אינטראקטיבי עם אירועים היסטוריים של האריה. 
- הוסיפו קישור למפת שמורות טבע שבהן ניתן לראות אריות בטבע.

הנה מדריך צבעוני אינטראקטיבי לפתרון קובייה הונגרית. הקוד הוא קובץ HTML יחיד שמציג שלבים מצוירים, הסברים וטיפים, ומתאים לכל המכשירים.

---

**מה הקובץ עושה** 
- מציג שלושה שלבים מרכזיים (הקשת הצלב, השלמת השכבות, סיום). 
- לכל שלב יש אנימציה של תנועות הקובייה ו‑הסבר טקסטואלי. 
- ניתן לעבור בין שלבים בעזרת כפתורים, והמצב נשמר ב‑`localStorage` כך שההתקדמות נשמרת גם אחרי רענון הדף. 
- כולל מצב “אור” ו‑“חשוך” לשימוש נוח במקומות שונים.

**איך להרחיב** 
- הוסיפו שלבים נוספים (אלגוריתמים מתקדמים) על‑ידי הוספת אובייקטים למערך `steps`. 
- ניתן לשלב וידאו או קישורים חיצוניים על‑ידי הוספת אלמנט `<iframe>` או `<a>` בתוך `description`. 
- לשנות את ערכת הצבעים – עדכנו את משתני CSS `--color-…` בחלק ה‑`:root`.

```html
<!-- file: rubik_guide.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>מדריך צבעוני לפתירת קובייה הונגרית</title>
<style>
:root {
 --bg-light: #f9fafb;
 --bg-dark: #1e1e2f;
 --primary: #4f46e5;
 --accent: #10b981;
 --text-light: #111827;
 --text-dark: #f3f4f6;
 --card-bg: #ffffff;
 --card-shadow: rgba(0,0,0,0.1);
}
[data-theme="dark"] {
 --bg-light: var(--bg-dark);
 --text-light: var(--text-dark);
 --card-bg: #2d2d44;
 --card-shadow: rgba(0,0,0,0.4);
}
body {
 margin:0; font-family: system-ui, sans-serif;
 background: var(--bg-light);
 color: var(--text-light);
 display:flex; flex-direction:column; align-items:center;
 min-height:100vh;
}
header {
 width:100%; padding:1rem 2rem;
 background: var(--primary);
 color:#fff; text-align:center;
 font-size:1.5rem; font-weight:600;
}
main {
 flex:1; width:100%; max-width:800px;
 padding:2rem;
 display:flex; flex-direction:column; align-items:center;
}
.card {
 background: var(--card-bg);
 border-radius:12px; box-shadow:0 4px 12px var(--card-shadow);
 padding:1.5rem; margin:1rem 0; width:100%;
 transition:transform .2s;
}
.card:hover { transform:scale(1.02); }
.step-title { font-size:1.3rem; margin-bottom:.5rem; color:var(--primary); }
.description { line-height:1.6; margin-bottom:1rem; }
.cube {
 width:200px; height:200px; margin:auto;
 perspective:800px;
}
.cube-inner {
 width:100%; height:100%; position:relative;
 transform-style:preserve-3d;
 animation: spin 8s linear infinite;
}
.face {
 position:absolute; width:66px; height:66px;
 background:#fff; border:2px solid #000;
 display:flex; align-items:center; justify-content:center;
 font-weight:bold; font-size:.8rem;
}
.front { transform:rotateY( 0deg) translateZ(33px); background:#ff4757; }
.back { transform:rotateY( 180deg) translateZ(33px); background:#2ed573; }
.right { transform:rotateY( 90deg) translateZ(33px); background:#1e90ff; }
.left { transform:rotateY( -90deg) translateZ(33px); background:#ffa502; }
.top { transform:rotateX( 90deg) translateZ(33px); background:#f1c40f; }
.bottom { transform:rotateX( -90deg) translateZ(33px); background:#e84393; }
@keyframes spin {
 from { transform:rotateX(0deg) rotateY(0deg); }
 to { transform:rotateX(360deg) rotateY(360deg); }
}
.controls { display:flex; gap:1rem; margin-top:1rem; }
button {
 padding:.6rem 1.2rem; border:none; border-radius:6px;
 background:var(--primary); color:#fff; cursor:pointer;
 transition:background .2s;
}
button:hover { background:#3b33c9; }
.toggle-theme {
 position:fixed; top:1rem; left:1rem;
 background:var(--accent); padding:.5rem .8rem;
}
</style>
</head>
<body>
<div class="toggle-theme"><button id="themeBtn">🌙 מצב חשוך</button></div>
<header>מדריך צבעוני לפתירת קובייה הונגרית</header>
<main>
 <div class="card" id="stepCard">
 <div class="step-title" id="stepTitle"></div>
 <div class="description" id="stepDesc"></div>
 <div class="cube"><div class="cube-inner" id="cubeAnim"></div></div>
 </div>
 <div class="controls">
 <button id="prevBtn">← שלב קודם</button>
 <button id="nextBtn">שלב הבא →</button>
 </div>
</main>

<script>
// נתוני שלבים – ניתן להרחיב בקלות
const steps = [
 {
 title: "שלב 1 – יצירת הצלב הלבן",
 description: "הצעד הראשון הוא ליצור צלב לבן על הפאה העליונה. יש למקם את קצוות הלבן כך שהם תואמים לצבעי המרכזים בצדדים.",
 cubeHTML: `<div class="face front">W</div>
 <div class="face back">W</div>
 <div class="face right">W</div>
